const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt = (v, key) => typeof v !== 'number' || !Number.isFinite(v) ? '—' : ['psnr','delta_e76','delta_e2000','training_hours','gpu_hours'].includes(key) ? v.toFixed(2) : v.toFixed(4);
const count = v => v==null?'—':Number(v).toLocaleString('en-US');
let DATA, view = {task:'mif',dataset:'orion',marker:'H&E',split:'test',protocol:'',search:'',sort:'lpips',asc:true,page:0,metricSet:'image'}, selected = new Set(), detailTab='overview';
let lastRows=[];
const cache=new Map();
const main=$('#main');
const dsName=id=>DATA.datasets.find(d=>d.id===id)?.name||id;
const metric=key=>DATA.metrics[key]||{label:key.replaceAll('_',' '),direction:'—',description:'Recorded training diagnostic. Scales depend on the recipe and configured weighting.'};
const info=key=>`<button class="info" type="button" data-tip="${esc(key)}" aria-label="About ${esc(metric(key).label)}">ⓘ</button>`;
const statusClass=s=>/evaluated/i.test(s)?'evaluated':/partial|evaluation in progress/i.test(s)?'partial':/train|running/i.test(s)?'training':'';
const status=s=>`<span class="status ${statusClass(s)}">${esc(s||'No result')}</span>`;
const option=(v,label,current)=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(label??v)}</option>`;
const intro=(title,description)=>`<div class="intro"><div><div class="eyebrow">Virtual staining research</div><h1>${title}</h1><p>${description}</p></div><div class="snapshot">Snapshot ${new Date(DATA.snapshot).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}<div class="stats"><span><strong>${DATA.datasets.length}</strong> datasets</span><span><strong>${DATA.runs.length}</strong> run records</span></div></div></div>`;

function benchmark(){
  const datasets=DATA.datasets.filter(d=>d.task===view.task);
  if(!datasets.some(d=>d.id===view.dataset))view.dataset=datasets[0].id;
  const ds=DATA.datasets.find(d=>d.id===view.dataset);
  const markers=ds.markers||['H&E'];if(!markers.includes(view.marker))view.marker=markers[0];
  const eligible=DATA.runs.filter(r=>r.datasets.includes(view.dataset)&&r.marker===view.marker);
  const evaluations=eligible.flatMap(r=>r.evaluations.filter(e=>e.dataset===view.dataset&&e.marker===view.marker&&e.split===view.split));
  const protocols=[...new Set(evaluations.map(e=>e.protocol))].sort();
  if(!protocols.includes(view.protocol))view.protocol=protocols.find(p=>p.startsWith('Box SSIM'))||protocols[0]||'';
  let rows=[];
  for(const run of eligible){
    const es=run.evaluations.filter(e=>e.dataset===view.dataset&&e.marker===view.marker&&e.split===view.split);
    const evaluation=es.find(e=>e.protocol===view.protocol);
    if(evaluation)rows.push({run,evaluation});
    else if(!es.length)rows.push({run,evaluation:null});
  }
  const search=view.search.toLowerCase();rows=rows.filter(({run})=>(run.name+' '+run.variant+' '+run.id+' '+run.state).toLowerCase().includes(search));
  const value=(r,k)=>k==='name'?r.run.name:k==='training_hours'?r.run.training_hours:r.evaluation?.metrics[k];
  rows.sort((a,b)=>{const av=value(a,view.sort),bv=value(b,view.sort);if(av==null)return bv==null? a.run.name.localeCompare(b.run.name):1;if(bv==null)return -1;const d=typeof av==='number'?av-bv:String(av).localeCompare(String(bv));return (view.asc?d:-d)||a.run.name.localeCompare(b.run.name)});
  lastRows=rows;const ranked=rows.filter(r=>r.evaluation?.rankable);
  const available=[...new Set(evaluations.flatMap(e=>Object.keys(e.metrics)))];
  let keys=['psnr','ssim','lpips','mae','delta_e76'];if(view.task==='ihc')keys.push('dab_od_mae','dab_correlation');
  if(view.metricSet==='stain')keys=available.filter(k=>/dab|nuclei|hematoxylin|eosin|delta_e/.test(k));
  if(view.metricSet==='representation')keys=available.filter(k=>/cosine|normalized_l2|dists|fid|kid|phv/.test(k));
  if(view.metricSet==='all')keys=available.filter(k=>!['loss','total_objective'].includes(k));
  if(!keys.length)keys=['psnr','ssim','lpips'];
  const best={};for(const key of [...keys,'training_hours']){const vals=[...new Set(ranked.map(r=>value(r,key)).filter(x=>typeof x==='number'&&Number.isFinite(x)))].sort((a,b)=>metric(key).direction==='↑'?b-a:a-b);best[key]=metric(key).direction==='—'?[]:vals.slice(0,2)}
  const pageSize=30,totalPages=Math.max(1,Math.ceil(rows.length/pageSize));view.page=Math.min(view.page,totalPages-1);const shown=rows.slice(view.page*pageSize,(view.page+1)*pageSize);
  main.innerHTML=intro('The virtual staining benchmark','Compare delivered models. Inspect what improves, where tissue detail is lost, and how each result was measured.')+`
    <div class="task-tabs" role="tablist" aria-label="Staining task">${[['mif','Multiplex IF → H&E'],['ihc','H&E → IHC'],['unstained','Unstained → H&E']].map(([id,label])=>`<button role="tab" aria-selected="${view.task===id}" class="${view.task===id?'active':''}" data-task="${id}">${label}<small>${DATA.datasets.filter(d=>d.task===id).length} dataset${id==='mif'?'':'s'}</small></button>`).join('')}</div>
    <section class="surface" aria-label="Benchmark results"><div class="filters">
      <label class="field">Dataset<select id="dataset">${datasets.map(d=>option(d.id,d.name,view.dataset)).join('')}</select></label>
      <label class="field">Target stain<select id="marker">${markers.map(m=>option(m,m,view.marker)).join('')}</select></label>
      <label class="field">Evaluation split<select id="split">${[['test','Held-out test'],['val','Validation'],['monitor','Training monitor'],['pilot','Pathology pilot (24 patches)']].map(([v,l])=>option(v,l,view.split)).join('')}</select></label>
      <label class="field">Metric protocol<select id="protocol">${protocols.length?protocols.map(p=>option(p,p,view.protocol)).join(''):option('','No completed evaluations','')}</select></label>
      <label class="field">Columns<select id="metricSet">${[['image','Image similarity'],['stain','Stain & nuclei'],['representation','Embeddings & texture'],['all','All recorded metrics']].map(([v,l])=>option(v,l,view.metricSet)).join('')}</select></label>
      <label class="field search-field">Find a model or run<input id="search" type="search" placeholder="Search models, recipes, status…" value="${esc(view.search)}"></label>
    </div><p class="protocol-note">${view.split==='pilot'?'The 24-patch pathology pilot is a separate exploratory evaluation and is excluded from full-test ranking.':view.split==='monitor'?'Latest training validation is provisional. These checkpoints are not ranked.':view.protocol.startsWith('Partial')?'Partial production evaluations are shown for inspection and excluded from ranking.':view.protocol?`Ranking applies within this dataset, stain, split, crop size and SSIM protocol. ${view.task==='ihc'?'Separate and pooled training share the same test fields.':''}`:'No final results yet. Queued, training and excluded methods remain visible.'}</p>
    <div class="toolbar"><span><strong>${rows.length}</strong> runs <span class="muted">· ${ranked.length} scored${protocols.length>1?` · ${protocols.length} protocol groups`:''}</span></span><div class="toolbar-actions"><span class="legend"><span><strong>Bold</strong> best</span><span><u>Underlined</u> second</span></span><button id="compare" ${selected.size<2?'disabled':''}>Compare (${selected.size}/3)</button><button id="export">Export CSV</button></div></div>
    <div class="table-wrap"><table><thead><tr><th aria-label="Select to compare"></th><th aria-sort="${view.sort==='name'?(view.asc?'ascending':'descending'):'none'}"><button class="sort" data-sort="name">Model / training recipe ${view.sort==='name'?view.asc?'▴':'▾':''}</button></th>${keys.map(k=>`<th class="number" aria-sort="${view.sort===k?(view.asc?'ascending':'descending'):'none'}"><button class="sort" data-sort="${k}">${esc(metric(k).label)} ${metric(k).direction}<span class="sort-state">${view.sort===k?(view.asc?'▴':'▾'):''}</span></button>${info(k)}</th>`).join('')}<th class="number"><button class="sort" data-sort="training_hours">Train (h) ${view.sort==='training_hours'?(view.asc?'▴':'▾'):''}</button>${info('training_hours')}</th><th>Status</th></tr></thead><tbody>${shown.map(({run,evaluation})=>`<tr><td><input class="check" type="checkbox" data-compare="${esc(run.id)}" aria-label="Compare ${esc(run.name)} ${esc(run.variant)}" ${selected.has(run.id)?'checked':''}></td><td class="model-cell"><a href="#/run/${encodeURIComponent(run.id)}${evaluation?'?eval='+evaluation.id:''}">${esc(run.name)}</a><span class="muted">${esc(run.variant)}${run.task==='ihc'?` · trained on ${run.datasets.map(dsName).join(' + ')}`:''}</span></td>${[...keys,'training_hours'].map(k=>{const v=value({run,evaluation},k);const cl=evaluation?.rankable&&v!=null?(v===best[k][0]?'best':v===best[k][1]?'second':''):'';return `<td class="number ${cl}">${fmt(v,k)}</td>`}).join('')}<td>${status(evaluation?.partial?'Partial evaluation':evaluation&&view.split!=='monitor'?'Evaluated':run.state)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No runs match these filters. Try another model name or dataset.</div>'}</div>
    <div class="toolbar"><span class="muted small">${rows.length?`${view.page*pageSize+1}–${Math.min((view.page+1)*pageSize,rows.length)} of ${rows.length} runs`:'0 runs'} · Click a model to explore the run</span><div class="pagination"><button id="prev" ${view.page===0?'disabled':''}>Previous</button><span>${view.page+1} / ${totalPages}</span><button id="next" ${view.page===totalPages-1?'disabled':''}>Next</button></div></div></section>
    <p class="page-note">Numerical ranks describe these delivered checkpoints. Training recipes and compute budgets differ. Small differences do not establish statistical superiority. Missing values remain blank.</p>`;
  $$('[data-task]').forEach(b=>b.onclick=()=>{view.task=b.dataset.task;view.protocol='';view.page=0;selected.clear();benchmark()});
  for(const key of ['dataset','marker','split','protocol','metricSet'])$('#'+key).onchange=e=>{view[key]=e.target.value;view.page=0;selected.clear();benchmark()};
  $('#search').oninput=e=>{view.search=e.target.value;view.page=0;const start=e.target.selectionStart;benchmark();$('#search').focus();$('#search').setSelectionRange(start,start)};
  $$('[data-sort]').forEach(b=>b.onclick=()=>{const key=b.dataset.sort;view.asc=view.sort===key?!view.asc:metric(key).direction!=='↑';view.sort=key;benchmark()});
  $$('[data-compare]').forEach(b=>b.onchange=()=>{if(b.checked&&selected.size>=3){b.checked=false;return}b.checked?selected.add(b.dataset.compare):selected.delete(b.dataset.compare);benchmark()});
  $('#prev').onclick=()=>{view.page--;benchmark()};$('#next').onclick=()=>{view.page++;benchmark()};$('#export').onclick=exportRows;$('#compare').onclick=()=>{location.hash='#/compare/'+[...selected].map(encodeURIComponent).join(',')};
  bindTooltips();
}
function download(filename,text,type='text/csv'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportRows(){const keys=[...new Set(lastRows.flatMap(r=>Object.keys(r.evaluation?.metrics||{})))];const cell=v=>`"${String(v??'').replaceAll('"','""')}"`;const lines=[['run','model','recipe','dataset','stain','split','protocol','tiles','rankable','training_hours',...keys]];lastRows.forEach(({run:r,evaluation:e})=>lines.push([r.id,r.name,r.variant,view.dataset,view.marker,view.split,e?.protocol,e?.n,e?.rankable,r.training_hours,...keys.map(k=>e?.metrics[k])]));download(`virtual-staining-${view.dataset}-${view.marker}-${view.split}.csv`,lines.map(row=>row.map(cell).join(',')).join('\n'))}
function bindTooltips(){const tip=$('#tooltip');$$('[data-tip]').forEach(el=>{const show=()=>{const m=metric(el.dataset.tip);tip.innerHTML=`<strong>${esc(m.label)} ${m.direction} · ${esc(m.unit||'')}</strong>${esc(m.description)}`;tip.hidden=false;const rect=el.getBoundingClientRect();tip.style.left=Math.min(Math.max(12,rect.left-100),innerWidth-tip.offsetWidth-12)+'px';tip.style.top=(rect.bottom+tip.offsetHeight+12>innerHeight?rect.top-tip.offsetHeight-8:rect.bottom+8)+'px';el.setAttribute('aria-describedby','tooltip')};el.onmouseenter=show;el.onfocus=show;el.onmouseleave=()=>tip.hidden=true;el.onblur=()=>tip.hidden=true;el.onclick=show;el.onkeydown=e=>{if(e.key==='Escape')tip.hidden=true}})}
async function loadRun(id){if(cache.has(id))return cache.get(id);const res=await fetch(`data/runs/${encodeURIComponent(id)}.json`,{cache:'no-store'});if(!res.ok)throw Error('This run could not be found.');const run=await res.json();cache.set(id,run);return run}
const facts=items=>`<div class="facts">${items.map(([label,value])=>`<div><span class="fact-label">${label}</span><span class="fact-value">${value==null||value===''?'Not recorded':esc(typeof value==='object'?JSON.stringify(value):value)}</span></div>`).join('')}</div>`;
function metricStrip(e){return `<div class="metric-strip">${['psnr','ssim','lpips','mae','delta_e76'].map(k=>`<div class="metric-tile"><label>${esc(metric(k).label)} ${metric(k).direction}${info(k)}</label><strong>${fmt(e?.metrics[k],k)}</strong><small>${esc(metric(k).unit)}</small></div>`).join('')}</div>`}
const runLink=(r,e)=>`#/run/${encodeURIComponent(r.id)}${e?'?eval='+e.id:''}`;
let activeRun='', chartCounter=0;
async function detail(id,eid){
  const run=await loadRun(id);if(activeRun!==id){detailTab='overview';activeRun=id}
  const e=run.evaluations.find(e=>e.id===eid)||run.evaluations.find(e=>e.split==='test'&&e.rankable)||run.evaluations.find(e=>e.split==='val'&&e.rankable)||run.evaluations[0];
  document.title=`${run.name} · Virtual Staining Benchmark`;
  main.innerHTML=`<div class="breadcrumbs"><a href="#/benchmark">Benchmark</a><span>/</span><span>${esc(e?dsName(e.dataset):run.datasets.map(dsName).join(' + '))}</span><span>/</span><span>${esc(run.name)}</span></div>
  <div class="detail-heading"><div><div class="eyebrow">${esc(DATA.datasets.find(d=>d.id===run.datasets[0])?.direction||'Virtual staining')}</div><h1>${esc(run.name)}</h1><p class="muted">${esc(run.variant)} · ${esc(run.marker)} · trained on ${run.datasets.map(dsName).join(' + ')}</p><div class="run-id muted">${esc(run.id)}</div></div><div>${status(run.state)}<div style="margin-top:12px"><a href="data/runs/${encodeURIComponent(run.id)}.json" download class="small">Download run data</a></div></div></div>
  ${run.evaluations.length?`<div class="gallery-controls" style="margin-top:20px"><label class="field">Result to inspect<select id="evaluation">${run.evaluations.map(ev=>option(ev.id,`${dsName(ev.dataset)} · ${ev.marker} · ${ev.split==='monitor'?'latest validation':ev.split} · ${ev.protocol}`,e?.id)).join('')}</select></label><span class="muted small">${count(e?.n)} tiles${e?.rankable?' · frozen evaluation':' · provisional / unranked'}</span></div>`:''}
  ${metricStrip(e)}
  <div class="detail-nav" role="tablist" aria-label="Run detail">${[['overview','Overview'],['curves','Training curves'],['tissue','Tissue comparisons'],['distribution','Metric distributions'],['provenance','Recipe & evidence']].map(([key,label])=>`<button role="tab" aria-selected="${detailTab===key}" class="${detailTab===key?'active':''}" data-detail="${key}">${label}</button>`).join('')}</div><div id="detail-content"></div>`;
  if($('#evaluation'))$('#evaluation').onchange=ev=>{location.hash=runLink(run,run.evaluations.find(e=>e.id===ev.target.value))};
  $$('[data-detail]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detail;detailContent(run,e);$$('[data-detail]').forEach(b=>{b.classList.toggle('active',b.dataset.detail===detailTab);b.setAttribute('aria-selected',b.dataset.detail===detailTab)})});
  detailContent(run,e);bindTooltips();
}
function detailContent(run,e){
  const root=$('#detail-content');
  const sourceNote=e?.partial?'This production evaluation is incomplete. Recorded core metrics are visible here, but the run is excluded from final ranking.':e?.split==='monitor'?'These are the latest validation measurements during training. They are not selected-checkpoint test results.':'';
  if(detailTab==='overview'){
    const tags=Object.keys(run.curves);const lpips=tags.find(t=>t==='val/lpips'),psnr=tags.find(t=>t==='val/psnr');
    const curveSections=[psnr,lpips].filter(Boolean);
    root.innerHTML=`${sourceNote?`<div class="callout">${sourceNote}</div>`:''}<div class="grid-two"><section class="panel"><h2>Training at a glance</h2>${facts([['Training wall time',run.training_hours!=null?`${fmt(run.training_hours,'training_hours')} h`:null],['GPU allocation',run.gpu_hours!=null?`${fmt(run.gpu_hours,'gpu_hours')} GPU h`:null],['Seed',run.seed],['Training tiles',run.train_tiles?count(run.train_tiles):null],['Selected checkpoint position',run.position||e?.position],['Last recorded step',run.last_step],['Stop condition',run.stop_reason],['Final evaluation time',run.evaluation_seconds!=null?`${run.evaluation_seconds.toFixed(1)} s`:null]])}<p class="small muted" style="margin-top:22px">${esc(run.time_definition||'Compute timing was not recorded in the available evidence. Training length and parent costs may differ between recipes.')}</p></section><section class="panel"><h2>What this result measures</h2><p class="small muted">${esc(e?.metric_protocol||e?.protocol||'No completed evaluation is available for this run.')}</p>${facts([['Checkpoint selection',run.selection||e?.selection],['Evaluation split',e?.split],['Evaluation tiles',e?count(e.n):null],['Target stain',run.marker]])}<p class="small muted" style="margin-top:20px">Image similarity alone does not establish nuclear, biological or diagnostic fidelity. These single-seed results compare the delivered recipes and training budgets.</p></section></div>
    ${curveSections.length?`<div class="grid-two">${curveSections.map(t=>`<section class="panel"><h3>${esc(metric(t.split('/').pop()).label)} during validation ${info(t.split('/').pop())}</h3>${lineChart(run.curves[t],t,run,e)}</section>`).join('')}</div>`:`<section class="panel"><h3>Training measurements</h3><p class="muted">${tags.length?'Saved objective curves are available in Training curves.':'Training scalar histories were not available in the saved evidence.'}</p></section>`}
    <section class="panel"><h2>Recorded evaluation metrics</h2>${evaluationTable(e)}${groupResults(e)}</section>${run.notes?`<div class="callout">${esc(run.notes)}</div>`:''}`;
    bindCharts();
  }else if(detailTab==='curves'){
    const tags=Object.keys(run.curves).sort();
    if(!tags.length){root.innerHTML=`<section class="panel empty"><h2>No scalar history available</h2><p>The saved snapshot contains run status and available results, but no training curves.</p></section>`;return}
    const defaults=['val/lpips','val/psnr','train/loss','train/l1'];let chosen=defaults.find(t=>tags.includes(t))||tags[0];
    root.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Training trajectory</h2><span class="small muted">${tags.length} recorded scalar series</span></div><label class="field">Metric / objective<select id="curve-metric">${tags.map(t=>option(t,t,chosen)).join('')}</select></label></div><div id="trajectory"></div><p class="small muted">Objectives and weighted terms have recipe-specific scales. Validation curves use their recorded checkpoint schedule. Test scores are final measurements and are not plotted as training progress.</p><a href="downloads/${encodeURIComponent(run.id)}_curves.csv" download>Download all recorded scalar points (CSV)</a></section>`;
    const draw=()=>{chosen=$('#curve-metric').value;const key=chosen.split('/').pop();$('#trajectory').innerHTML=`<p class="small muted">${esc(metric(key).description)} ${info(key)}</p>${lineChart(run.curves[chosen],chosen,run,e)}<p class="chart-caption">${count(run.curve_counts[chosen])} recorded points. ${run.curve_counts[chosen]>700?'Plot shows 700 evenly spaced points; the download preserves every recorded value.':'Every recorded value is shown.'}</p>`;bindCharts();bindTooltips()};$('#curve-metric').onchange=draw;draw();
  }else if(detailTab==='tissue'){
    if(!run.gallery.length){root.innerHTML=`<section class="panel empty"><h2>Tissue previews unavailable in this snapshot</h2><p>${run.task==='ihc'?'The breast production previews were moved to the Ubuntu archive. Complete result means and validation trajectories are available.':'No paired image previews were retained in the accessible run evidence.'}</p></section>`;return}
    root.innerHTML=`<section class="panel"><div class="panel-head"><h2>Prediction beside ground truth</h2><span class="small muted">${run.gallery.length} retained fields</span></div><div class="gallery-controls"><label class="field">Saved field<select id="field">${run.gallery.map((im,i)=>option(String(i),`${im.label}${im.step!=null?' · step/epoch '+im.step:''}`,'0')).join('')}</select></label><label class="field">View<select id="image-mode"><option value="pair">Side by side</option><option value="swipe">Swipe comparison</option></select></label></div><div id="images"></div><div id="gallery-note" class="chart-caption"></div></section>`;
    const draw=()=>{const im=run.gallery[Number($('#field').value)];const gt=esc(im.gt),pred=esc(im.pred);$('#images').innerHTML=$('#image-mode').value==='pair'?`<div class="image-pair"><div class="image-frame"><figure><img src="${gt}" alt="Ground-truth stained tissue for ${esc(im.label)}"><figcaption>Chemically stained ground truth</figcaption></figure></div><div class="image-frame"><figure><img src="${pred}" alt="Virtual staining prediction for ${esc(im.label)}"><figcaption class="pred-label">${esc(run.name)} prediction</figcaption></figure></div></div>`:`<div class="swipe-labels"><span>Prediction</span><span>Ground truth</span></div><div class="swipe" id="swipe"><img src="${gt}" alt="Ground-truth tissue"><img class="overlay" src="${pred}" alt="Virtual staining prediction"></div><label class="field" style="margin-top:18px">Comparison boundary<input class="slider" id="boundary" aria-label="Slide comparison boundary" type="range" min="0" max="100" value="50"></label>`;$('#gallery-note').textContent=`${im.split==='pilot'?'A seeded 24-patch pilot, separate from the full-test evaluation.':im.checkpoint==='selected final checkpoint'?'Fixed preview fields from the selected checkpoint; examples do not represent the full metric distribution.':'Fixed validation preview fields; examples do not represent the full metric distribution.'} ${im.checkpoint}. Pixels are preserved from the saved output.`;if($('#boundary'))$('#boundary').oninput=ev=>{$('#swipe').style.setProperty('--position',ev.target.value+'%');$('.overlay').style.clipPath=`inset(0 ${100-ev.target.value}% 0 0)`}};$('#field').onchange=draw;$('#image-mode').onchange=draw;draw();
  }else if(detailTab==='distribution'){
    const splits=Object.keys(run.distributions);
    if(!splits.length){root.innerHTML=`<section class="panel empty"><h2>Per-tile metrics unavailable</h2><p>Only aggregate scores were retained in the accessible evidence. A distribution cannot be recovered from a mean.${run.task==='ihc'?' Breast per-tile outputs require the archived run files.':''}</p></section>`;return}
    let split=splits.includes(e?.split)?e.split:splits[0];const keys=Object.keys(run.distributions[split]);
    root.innerHTML=`<section class="panel"><div class="panel-head"><h2>Variation across tissue fields</h2><label class="field">Split<select id="dist-split">${splits.map(s=>option(s,s,split)).join('')}</select></label></div><p class="small muted">Violin width shows the observed density, with median and interquartile range inside. These distributions describe tile variation, not uncertainty across repeated training runs.</p><label class="field">Metric<select id="dist-metric">${keys.map(k=>option(k,metric(k).label,keys.includes('lpips')?'lpips':keys[0])).join('')}</select></label><div id="violin"></div><a id="dist-download" download>Download per-tile measurements (CSV)</a></section>`;
    const draw=()=>{split=$('#dist-split').value;const k=$('#dist-metric').value,s=run.distributions[split][k];$('#violin').innerHTML=violin(s,k);$('#dist-download').href=`downloads/${encodeURIComponent(run.id)}_${split}_per_tile.csv`;bindTooltips()};$('#dist-metric').onchange=draw;$('#dist-split').onchange=()=>{const old=$('#dist-metric').value;$('#dist-metric').innerHTML=Object.keys(run.distributions[$('#dist-split').value]).map(k=>option(k,metric(k).label,old)).join('');draw()};draw();
  }else if(detailTab==='provenance'){
    root.innerHTML=`<section class="panel"><h2>Recipe and reproducibility</h2>${facts([['Run ID',run.id],['Seed',run.seed],['Crop size',run.crop_size?run.crop_size+' pixels':run.task==='ihc'?'256 native pixels':null],['Training datasets',run.datasets.map(dsName).join(' + ')],['Selected checkpoint position',run.position||e?.position],['Checkpoint selection',run.selection||e?.selection],['Time definition',run.time_definition],['Evaluation protocol',e?.metric_protocol||e?.protocol]])}<details open><summary>Checkpoint and data fingerprints</summary><p class="small">Checkpoint SHA-256</p><div class="hash">${esc(run.checkpoint_sha256||e?.checkpoint_sha256||'Not recorded')}</div><p class="small">Evaluation manifest SHA-256</p><div class="hash">${esc(e?.manifest_sha256||'Not recorded')}</div><p class="small">Training source SHA-256</p><div class="hash">${esc(run.source_sha256||'Not recorded')}</div></details><details><summary>Training configuration</summary><pre class="config">${esc(run.configuration||'Configuration unavailable')}</pre></details><details><summary>Source records</summary><ul class="small muted">${run.sources.map(s=>`<li>${s.sheet?`${esc(s.sheet)} · Excel row ${s.row}`:esc(s.file)}${s.record?' · '+esc(s.record):''}</li>`).join('')}</ul></details><p class="small muted">Raw checkpoints and original datasets are not part of this website. Dataset and model references are listed in Datasets and Models & coverage.</p></section>`;
  }
  bindTooltips();
}
function evaluationTable(e){if(!e)return '<p class="muted">No evaluation result is available.</p>';return `<div class="table-wrap"><table><thead><tr><th>Metric</th><th class="number">Value</th><th>Unit</th><th class="number">Valid tiles</th></tr></thead><tbody>${Object.entries(e.metrics).map(([k,v])=>`<tr><td>${esc(metric(k).label)} ${metric(k).direction}${info(k)}</td><td class="number">${fmt(v,k)}</td><td class="small muted">${esc(metric(k).unit||'recorded units')}</td><td class="number">${count(e.coverage?.[k]??e.n)}</td></tr>`).join('')}</tbody></table></div>`}
function groupResults(e){if(!e?.group_macro)return '';return `<details style="margin-top:20px"><summary>Group means and 95% bootstrap intervals</summary><p class="small muted">Groups receive equal weight. Bootstrap unit: ${esc(e.bootstrap_unit||'recorded source group')}. These intervals describe this cohort’s groups; they do not measure variation across repeated training seeds.</p><div class="table-wrap"><table><thead><tr><th>Metric</th><th class="number">Group mean</th><th class="number">95% interval</th></tr></thead><tbody>${Object.entries(e.group_macro).filter(([k,v])=>v?.ci95).map(([k,v])=>`<tr><td>${esc(metric(k).label)} ${info(k)}</td><td class="number">${fmt(v.group_macro,k)}</td><td class="number">${fmt(v.ci95[0],k)} – ${fmt(v.ci95[1],k)}</td></tr>`).join('')}</tbody></table></div></details>`}
const chartData=new Map();
function lineChart(points,tag,run,e){
  const id='chart-'+(++chartCounter);const w=760,h=300,pad={l:65,r:20,t:20,b:45};
  if(!points?.length)return '<div class="empty">No recorded data points.</div>';
  let xmin=points[0][0],xmax=points.at(-1)[0];if(xmin===xmax)xmax=xmin+1;let ymin=Math.min(...points.map(p=>p[1])),ymax=Math.max(...points.map(p=>p[1]));const margin=(ymax-ymin)*.1||Math.abs(ymin)*.05||.1;ymin-=margin;ymax+=margin;
  const x=v=>pad.l+(v-xmin)/(xmax-xmin)*(w-pad.l-pad.r),y=v=>h-pad.b-(v-ymin)/(ymax-ymin)*(h-pad.t-pad.b);
  const path=points.map((p,i)=>(i?'L':'M')+x(p[0]).toFixed(2)+','+y(p[1]).toFixed(2)).join(' ');
  const val=tag.startsWith('val/');const axis=run.curve_axis==='epoch'?(val?'Epoch':'Logged optimizer step'):'Optimizer step';
  chartData.set(id,{points,xmin,xmax,ymin,ymax,w,h,pad,x,y,tag,axis});
  const grids=Array.from({length:5},(_,i)=>{const v=ymin+(ymax-ymin)*i/4;return `<line x1="${pad.l}" y1="${y(v)}" x2="${w-pad.r}" y2="${y(v)}"/><text x="${pad.l-12}" y="${y(v)+4}" text-anchor="end">${Math.abs(v)>=100?v.toFixed(0):v.toFixed(3)}</text>`}).join('');
  const ticks=Array.from({length:5},(_,i)=>{const v=xmin+(xmax-xmin)*i/4;return `<text x="${x(v)}" y="${h-pad.b+24}" text-anchor="middle">${Math.round(v).toLocaleString('en-US')}</text>`}).join('');
  let position=run.position||e?.position;try{if(typeof position==='string')position=JSON.parse(position)}catch{}
  const selected=typeof position==='object'&&position?(axis==='Epoch'?position.epoch:position.global_step||position.step):null;
  const marker=selected!=null&&selected>=xmin&&selected<=xmax?`<line x1="${x(selected)}" x2="${x(selected)}" y1="${pad.t}" y2="${h-pad.b}" style="stroke:#c3447f;stroke-dasharray:4 4"/><text x="${Math.min(x(selected)+6,w-115)}" y="${pad.t+12}" style="fill:#c3447f">Selected</text>`:'';
  return `<svg id="${id}" class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(tag)} over ${esc(axis)}"><title>${esc(tag)} training trajectory</title>${grids}${ticks}${marker}<path d="${path}" fill="none" stroke="${val?'#4159dc':'#c3447f'}" stroke-width="2.4" vector-effect="non-scaling-stroke"/><line class="crosshair" x1="0" x2="0" y1="${pad.t}" y2="${h-pad.b}" style="stroke:#91a0bf;stroke-dasharray:3 3;visibility:hidden"/><circle class="chart-point" r="5" fill="${val?'#4159dc':'#c3447f'}" stroke="white" stroke-width="2" style="visibility:hidden"/><text x="${w/2}" y="${h-3}" text-anchor="middle">${axis}</text></svg><div id="${id}-tip" class="chart-tip" aria-live="polite">${val?'Validation':'Training'} · ${points.length} plotted measurements</div>`;
}
function bindCharts(){for(const svg of $$('.chart')){const c=chartData.get(svg.id);if(!c)continue;svg.onpointermove=ev=>{const r=svg.getBoundingClientRect();const target=c.xmin+((ev.clientX-r.left)/r.width*c.w-c.pad.l)/(c.w-c.pad.l-c.pad.r)*(c.xmax-c.xmin);const p=c.points.reduce((best,p)=>Math.abs(p[0]-target)<Math.abs(best[0]-target)?p:best);const cross=$('.crosshair',svg),point=$('.chart-point',svg);cross.setAttribute('x1',c.x(p[0]));cross.setAttribute('x2',c.x(p[0]));cross.style.visibility='visible';point.setAttribute('cx',c.x(p[0]));point.setAttribute('cy',c.y(p[1]));point.style.visibility='visible';$('#'+svg.id+'-tip').textContent=`${c.axis} ${count(p[0])} · ${c.tag} ${p[1].toPrecision(6)}`};svg.onpointerleave=()=>{$('.crosshair',svg).style.visibility='hidden';$('.chart-point',svg).style.visibility='hidden'}}}
function violin(s,key){if(!s)return '<div class="empty">No finite per-tile observations.</div>';const w=760,h=360,left=80,top=25,bottom=310,mid=380,width=105;let min=s.quantiles[0],max=s.quantiles[6];if(min===max){min-=.01;max+=.01}const y=v=>bottom-(v-min)/(max-min)*(bottom-top);const path=s.density.map((p,i)=>(i?'L':'M')+(mid+p[1]*width)+','+y(p[0])).join(' ')+[...s.density].reverse().map(p=>'L'+(mid-p[1]*width)+','+y(p[0])).join(' ')+'Z';const q=s.quantiles;return `<div class="panel-head" style="margin-top:24px"><h3>${esc(metric(key).label)} ${metric(key).direction}${info(key)}</h3><span class="small muted">${count(s.n)} finite tiles</span></div><svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(metric(key).label)} per-tile distribution">${Array.from({length:5},(_,i)=>{const v=min+(max-min)*i/4;return `<line x1="${left}" x2="680" y1="${y(v)}" y2="${y(v)}"/><text x="${left-12}" y="${y(v)+4}" text-anchor="end">${fmt(v,key)}</text>`}).join('')}<path d="${path}" fill="#dce3ff" stroke="#4159dc" stroke-width="1.7"/><line x1="${mid}" x2="${mid}" y1="${y(q[1])}" y2="${y(q[5])}" style="stroke:#202e4a;stroke-width:2"/><line x1="${mid}" x2="${mid}" y1="${y(q[2])}" y2="${y(q[4])}" style="stroke:#202e4a;stroke-width:7"/><circle cx="${mid}" cy="${y(q[3])}" r="5" fill="white"/><text x="${mid}" y="345" text-anchor="middle">${esc(metric(key).label)}</text></svg>${facts([['Median',fmt(q[3],key)],['Interquartile range',`${fmt(q[2],key)} – ${fmt(q[4],key)}`],['Mean ± standard deviation',`${fmt(s.mean,key)} ± ${fmt(s.sd,key)}`],['5th–95th percentile',`${fmt(q[1],key)} – ${fmt(q[5],key)}`]])}<p class="chart-caption">${esc(s.method)}. Variation across tiles is not a confidence interval on model superiority.</p>`}

function modelPage(){
  main.innerHTML=intro('Models & coverage','Every model in the Excel inventory, plus the additional families found in saved training runs.')+`<div class="callout">Excel priority indicates implementation priority, not model quality. A planned, excluded or deferred method has no invented benchmark score.</div><div class="filters" style="padding-left:0"><label class="field search-field">Find a model<input id="model-search" type="search" placeholder="Search model, backbone, training family…"></label><label class="field">Coverage<select id="model-filter"><option value="all">All model families</option><option value="scored">Has held-out results</option><option value="pending">No held-out results yet</option></select></label></div><div id="model-cards" class="model-grid"></div>`;
  const draw=()=>{const q=$('#model-search').value.toLowerCase(),f=$('#model-filter').value;const models=DATA.models.filter(m=>(m.name+' '+m.backbone+' '+m.family).toLowerCase().includes(q)&&(f==='all'||(f==='scored'?m.evaluated_runs>0:!m.evaluated_runs)));$('#model-cards').innerHTML=models.map(m=>`<article class="model-card"><div class="eyebrow">${m.priority?`Excel priority ${m.priority}`:'Supplemental family'}</div><h3 style="margin-top:10px">${esc(m.name)}</h3><p>${esc(m.backbone||m.family||'Recorded training family')}</p><div class="tags">${m.datasets.map(d=>`<span class="tag">${esc(dsName(d))}</span>`).join('')||'<span class="tag">No completed benchmark</span>'}</div><p><strong>${m.evaluated_runs}</strong> runs with held-out results · ${m.runs} run records</p><details><summary>Readiness and limitations</summary><p>${esc(m.notes||m.recommendation||'See individual run configurations for method adaptations.')}</p>${m.orion?`<p>ORION: ${esc(m.orion)}</p>`:''}${m.breast?`<p>Breast: ${esc(m.breast)}</p>`:''}</details><div style="display:flex;justify-content:space-between;gap:15px;margin-top:14px">${m.runs?`<button data-model="${esc(m.id)}">Explore runs</button>`:'<span class="small muted">No saved run</span>'}${typeof m.url==='string'&&m.url.startsWith('https://')?`<a class="small" href="${esc(m.url)}" target="_blank" rel="noopener">Author source</a>`:''}</div></article>`).join('')||'<div class="empty">No matching models.</div>';$$('[data-model]').forEach(b=>b.onclick=()=>{const m=DATA.models.find(m=>m.id===b.dataset.model);const r=DATA.runs.find(r=>r.model===m.id&&r.evaluations.some(e=>e.rankable&&e.split==='test'))||DATA.runs.find(r=>r.model===m.id);view.task=r.task;view.dataset=r.datasets[0];view.marker=r.marker;view.search=r.name;view.page=0;view.protocol='';view.split='test';location.hash='#/benchmark'})};$('#model-search').oninput=draw;$('#model-filter').onchange=draw;draw();
}
function datasetPage(){main.innerHTML=intro('Six datasets. Three staining tasks.','Dataset identity, target stain, tissue scale and pairing determine what a benchmark result can tell you.')+`<div class="dataset-grid">${DATA.datasets.map(d=>{const counts=d.counts||{};const rows=typeof counts.train==='object'?d.markers.map(m=>[m,counts.train[m],counts.val[m],counts.test[m]]):[['All',counts.train,counts.val,counts.test]];return `<article class="dataset-card"><div class="eyebrow">${esc(d.direction)}</div><h2>${esc(d.name)}</h2><div class="small muted">${esc(d.tissue)}</div><p>${esc(d.description)}</p><div class="table-wrap"><table><thead><tr><th>Stain</th><th>Train</th><th>Val</th><th>Test</th></tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td>${i===0?esc(v):v!=null?count(v):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>${esc(d.notes)}</p>${d.slides?`<p>Slides: ${d.slides.train} train / ${d.slides.val} validation / ${d.slides.test} test.</p>`:''}${d.cases?`<p>Case groups: ${d.cases.train} / ${d.cases.val} / ${d.cases.test}.</p>`:''}<button data-dataset="${esc(d.id)}">View benchmark</button>${d.source?`<p><a href="${esc(d.source)}" target="_blank" rel="noopener">Dataset / source</a></p>`:''}</article>`}).join('')}</div>`;$$('[data-dataset]').forEach(b=>b.onclick=()=>{const d=DATA.datasets.find(d=>d.id===b.dataset.dataset);view.dataset=d.id;view.task=d.task;view.marker=d.markers?.[0]||'H&E';view.search='';view.split='test';view.protocol='';view.page=0;location.hash='#/benchmark'})}
function methodsPage(){
  main.innerHTML=intro('Read the evidence behind the ranking','A good-looking stain, a close pixel match and preserved biology are different questions.')+`<section class="panel methods-copy"><h2>What is comparable?</h2><p>Each table fixes the dataset, target stain, evaluation split, crop size and SSIM implementation. Results from incompatible historical protocols are placed in separate groups. Missing held-out results remain visible as unscored run records.</p><p>Best and second-best values are computed from distinct full-precision values in the displayed comparison group. Exact ties share the same treatment. Filtering changes the comparison set. Bold and underline indicate numerical order, not a statistical test.</p><h3>Checkpoint selection and training curves</h3><p>Final evaluation reloads the saved selected checkpoint. The selection policy is retained per run; newer campaigns minimize full-validation AlexNet LPIPS. Test data never selects a checkpoint. Curves show the recorded scalar values, with no smoothing. Downloads retain all available scalar points, while dense plots show up to 700 evenly spaced points.</p><h3>Compute and pooling</h3><p>Training wall time and GPU allocation are recorded once per training run. A pooled run appears in multiple dataset and split views; do not add its compute repeatedly. Continuation time may exclude parent training. Different recipes and budgets mean these are delivered-model comparisons, rather than isolated architecture comparisons.</p><h3>Image and biological evidence</h3><p>Saved validation previews are illustrative fixed fields. Their checkpoint can differ from the selected final model. The 24-patch ORION pathology pilot uses seeded held-out fields and is separate from full-test results. Nucleus reference labels are automatic detector outputs on real H&E. They are not manual annotations or validated diagnostic endpoints. Embedding similarities do not guarantee correct cell locations.</p><h3>Distributions and uncertainty</h3><p>Violin plots use actual finite per-tile measurements. Gaussian kernel density uses a Silverman bandwidth, with a minimum of one two-hundredth of the observed range. Median, quartiles and 5th–95th percentiles are empirical. Tile variation is not uncertainty across repeated training seeds; tiles from the same slide can be correlated.</p><h3>Current coverage</h3><p>The workbook contains ${DATA.audit.model_priority_rows} model-priority entries and ${DATA.audit.orion_inventory_rows} ORION inventory rows. All ${DATA.audit.breast_runs} breast production runs are retained. ${DATA.audit.dataset_result_rows_verified} dataset result rows (${count(DATA.audit.verified_cells)} metric cells) were checked against their production evidence. Additional cluster runs supplement the workbook.</p><p>Breast production tissue previews and per-tile distributions are held in an external archive that was unavailable when this snapshot was assembled. Their aggregate metrics and convergence histories are available. Pending models have no fabricated values. Unstained production evaluations with incomplete specialist metrics are excluded from final ranking.</p><div class="toolbar-actions"><a href="downloads/results.csv" download>Download all results (CSV)</a><a href="data/reconciliation.json" download>Download workbook reconciliation</a></div><p class="small muted" style="margin-top:20px">Workbook SHA-256: <span class="hash">${esc(DATA.audit.workbook_sha256)}</span></p></section><h2 style="margin-top:28px">Metric glossary</h2><label class="field search-field" style="max-width:550px;margin-bottom:22px">Find a metric<input id="metric-search" type="search" placeholder="PSNR, LPIPS, stain, nuclei, embeddings…"></label><div id="glossary" class="glossary"></div>`;
  const draw=()=>{const q=$('#metric-search').value.toLowerCase();$('#glossary').innerHTML=Object.entries(DATA.metrics).filter(([k,m])=>(k+' '+m.label+' '+m.description).toLowerCase().includes(q)).map(([k,m])=>`<article class="glossary-item"><h3>${esc(m.label)} <span class="muted">${m.direction}</span></h3><span class="small muted">${esc(m.unit)}</span><p>${esc(m.description)}</p></article>`).join('')};$('#metric-search').oninput=draw;draw();
}
async function comparison(ids){const loaded=await Promise.all(ids.map(loadRun));const rows=loaded.map(r=>({run:r,evaluation:r.evaluations.find(e=>e.dataset===view.dataset&&e.marker===view.marker&&e.split===view.split&&e.protocol===view.protocol)||r.evaluations.find(e=>e.split==='test'&&e.rankable)||r.evaluations[0]}));const keys=rows.map(({evaluation:e})=>e?`${e.dataset}|${e.marker}|${e.split}|${e.protocol}|${e.n}`:'none');const compatible=new Set(keys).size===1&&keys[0]!=='none';main.innerHTML=`<div class="breadcrumbs"><a href="#/benchmark">Benchmark</a><span>/</span><span>Compare runs</span></div><h1>Compare training runs</h1><p class="muted">${compatible?'Same dataset, stain, split and metric protocol.': 'These runs have different evaluation settings. Inspect their evidence without treating the scores as a matched ranking.'}</p><div class="compare-grid">${rows.map(({run:r,evaluation:e})=>`<section><div class="panel"><h2>${esc(r.name)}</h2><p class="small muted">${esc(r.variant)}</p><p class="small">${e?`${dsName(e.dataset)} · ${e.split} · ${esc(e.protocol)}`:'No scored evaluation'}</p><a href="${runLink(r,e)}">Open run details</a>${metricStrip(e)}${facts([['Training wall time',r.training_hours!=null?fmt(r.training_hours,'training_hours')+' h':null],['GPU allocation',r.gpu_hours!=null?fmt(r.gpu_hours,'gpu_hours')+' GPU h':null],['Seed',r.seed],['Selected position',r.position]])}</div>${r.curves['val/lpips']?`<div class="panel"><h3>Validation LPIPS</h3>${lineChart(r.curves['val/lpips'],'val/lpips',r,e)}</div>`:''}${r.gallery.length?`<div class="panel"><h3>Illustrative prediction</h3><div class="image-frame"><img src="${esc(r.gallery[0].pred)}" alt="${esc(r.name)} saved tissue prediction"></div><p class="small muted">${esc(r.gallery[0].label)}. Fields may differ across runs; open each run to inspect its paired ground truth.</p></div>`:''}</section>`).join('')}</div>`;bindCharts();bindTooltips()}
async function route(){
  if(!DATA)return;$('#tooltip').hidden=true;chartData.clear();document.title='Virtual Staining Benchmark';const hash=location.hash||'#/benchmark',path=hash.split('?')[0];$$('nav a').forEach(a=>a.classList.toggle('active',a.hash===path));
  try{if(path.startsWith('#/run/'))await detail(decodeURIComponent(path.slice(6)),new URLSearchParams(hash.split('?')[1]||'').get('eval'));else if(path==='#/models')modelPage();else if(path==='#/datasets')datasetPage();else if(path==='#/methods')methodsPage();else if(path.startsWith('#/compare/'))await comparison(path.slice(10).split(',').map(decodeURIComponent).slice(0,3));else benchmark();window.scrollTo(0,0)}catch(e){main.innerHTML=`<div class="empty"><h1>This view could not load</h1><p>${esc(e.message)}</p><a href="#/benchmark">Return to benchmark</a></div>`}
}
$('.skip-link').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'})};
window.addEventListener('hashchange',route);
try{const response=await fetch('data/index.json',{cache:'no-store'});if(!response.ok)throw Error('Data request failed');DATA=await response.json();route()}catch(e){main.innerHTML='<div class="empty"><h1>Results could not load</h1><p>Reload the page to try again.</p><button onclick="location.reload()">Reload</button></div>'}
